struct TestServer {
    addr: SocketAddr,
    shutdown: Option<oneshot::Sender<()>>,
    handle: Option<JoinHandle<()>>,
}

impl TestServer {
    async fn start() -> Self {
        let listener = TcpListener::bind("127.0.0.1:0")
            .await
            .expect("bind test server");
        let addr = listener.local_addr().expect("server addr");
        let (shutdown, mut shutdown_rx) = oneshot::channel::<()>();
        let handle = tokio::spawn(async move {
            loop {
                tokio::select! {
                    _ = &mut shutdown_rx => {
                        break;
                    }
                    accept = listener.accept() => {
                        match accept {
                            Ok((socket, _)) => {
                                tokio::spawn(async move {
                                    let _ = handle_connection(socket).await;
                                });
                            }
                            Err(_) => break,
                        }
                    }
                }
            }
        });

        Self {
            addr,
            shutdown: Some(shutdown),
            handle: Some(handle),
        }
    }

    fn url(&self, path: &str) -> String {
        format!("http://{}{}", self.addr, path)
    }

    async fn shutdown(mut self) {
        if let Some(sender) = self.shutdown.take() {
            let _ = sender.send(());
        }
        if let Some(handle) = self.handle.take() {
            let _ = handle.await;
        }
    }
}

impl Drop for TestServer {
    fn drop(&mut self) {
        if let Some(sender) = self.shutdown.take() {
            let _ = sender.send(());
        }
        if let Some(handle) = self.handle.take() {
            handle.abort();
        }
    }
}

async fn handle_connection(mut socket: TcpStream) -> std::io::Result<()> {
    let mut buffer = [0u8; 8192];
    let read = socket.read(&mut buffer).await?;
    if read == 0 {
        return Ok(());
    }
    let request = String::from_utf8_lossy(&buffer[..read]);
    let mut parts = request.lines().next().unwrap_or_default().split_whitespace();
    let method = parts.next().unwrap_or("GET");
    let raw_path = parts.next().unwrap_or("/");
    let path = raw_path.split('?').next().unwrap_or("/");

    let (status, body, content_type) = route_request(method, path);
    let body_bytes = body.as_bytes();
    let response = format!(
        "HTTP/1.1 {status}\r\nContent-Type: {content_type}\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{}",
        body_bytes.len(),
        body
    );
    socket.write_all(response.as_bytes()).await?;
    Ok(())
}

fn load_harness_page() -> String {
    std::fs::read_to_string(HARNESS_PAGE_PATH).expect("read harness page")
}

fn route_request(method: &str, path: &str) -> (&'static str, String, &'static str) {
    if method != "GET" {
        return (
            "405 Method Not Allowed",
            "method not allowed".to_string(),
            "text/plain",
        );
    }
    match path {
        "/" | "/harness" => (
            "200 OK",
            load_harness_page(),
            "text/html; charset=utf-8",
        ),
        "/favicon.ico" => ("404 Not Found", "not found".to_string(), "text/plain"),
        _ => ("404 Not Found", "not found".to_string(), "text/plain"),
    }
}

fn find_element<'a>(
    observation: &'a Observation,
    role: &str,
    name: &str,
) -> &'a ElementRef {
    observation
        .elements
        .iter()
        .find(|element| {
            element.role.eq_ignore_ascii_case(role)
                && element
                    .name
                    .as_deref()
                    .map(|value| value.eq_ignore_ascii_case(name))
                    .unwrap_or(false)
        })
        .unwrap_or_else(|| panic!("missing element role={role} name={name}"))
}

fn find_element_by_roles<'a>(
    observation: &'a Observation,
    roles: &[&str],
    name: &str,
) -> &'a ElementRef {
    observation
        .elements
        .iter()
        .find(|element| {
            roles.iter().any(|role| element.role.eq_ignore_ascii_case(role))
                && element
                    .name
                    .as_deref()
                    .map(|value| value.eq_ignore_ascii_case(name))
                    .unwrap_or(false)
        })
        .unwrap_or_else(|| panic!("missing element roles={roles:?} name={name}"))
}

async fn wait_for_visible_text(
    browser: &CdpBrowser,
    needle: &str,
) -> Observation {
    for _ in 0..20 {
        let snapshot = browser.snapshot().await.expect("snapshot retry");
        if snapshot.visible_text.contains(needle) {
            return snapshot;
        }
        sleep(Duration::from_millis(100)).await;
    }
    panic!("expected visible text to include {needle}");
}

